def format_citations({{answer}}, {{sources}}):
    text = {{answer}}
    refs = []
    for i, s in enumerate({{sources}}, 1):
        marker = f"[{i}]"
        text = text.replace(s["id"], marker)
        refs.append(f"{marker} {s['title']} - {s['url']}")
    return text + "\n\nReferences:\n" + "\n".join(refs)
